import {modules,causes,protocol,ages,weights,medications,energies} from './data.js';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',syringe:'<path d="m18 2 4 4m-3-1-5 5m-8 2 6 6m-9 3 3-3m0 0-1-4 9-9 5 5-9 9-4-1Z"/>',airway:'<path d="M12 2v9M8 3v8l-5 7a2 2 0 0 0 2 3h3l4-7 4 7h3a2 2 0 0 0 2-3l-5-7V3"/>',brain:'<path d="M12 5c-4-5-8 0-6 3-5 1-4 7-1 8-1 5 5 7 7 3V5Zm0 0c4-5 8 0 6 3 5 1 4 7 1 8 1 5-5 7-7 3M6 8l3 2m-4 6 4-2m9-6-3 2m4 6-4-2"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="M12 8v8m-4-4h8"/>',child:'<circle cx="12" cy="5" r="3"/><path d="M5 10h14m-7-2v8m0-1-5 7m5-7 5 7"/>',book:'<path d="M12 5c-4-3-7-3-10-2v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-3-1-6-1-10 2Zm0 0v16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({checks:{},causes:{},fields:{},started:null,elapsed:0,running:false,age:null,adultMax:'',filter:''});
let state;try{state=Object.assign(blank(),JSON.parse(sessionStorage.getItem('wfd-encounter-v1')||'{}'));}catch{state=blank()}
let page=location.hash.slice(1)||'home',query='',modal=false;
const save=()=>{try{sessionStorage.setItem('wfd-encounter-v1',JSON.stringify(state));}catch{}};
const totalChecks=()=>Object.values(state.checks).filter(Boolean).length;
const count=m=>m.sections.reduce((n,s)=>n+s[1].length,0);
const completed=m=>Object.keys(state.checks).filter(k=>k.startsWith(m.id+'-')&&state.checks[k]).length;
const source=(label,p=1)=>`<a class="source" href="${protocol}#page=${p}" target="_blank" rel="noopener">${icon('book')}${label} ↗</a>`;
function nav(id,label,i){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${page===id?'<i></i>':''}</button>`;}
function shell(){return `<aside class="sidebar"><a href="#home" class="brand"><div class="crest">${icon('shield')}</div><span>WOODLAWN<span>FIRE DEPARTMENT</span></span></a><div class="sidebar-label">EMS FIELD GUIDE</div>${nav('home','Overview','grid')}<div class="sidebar-label space">CHECKLISTS</div>${modules.map(m=>nav(m.id,m.short,m.icon)).join('')}<div class="sidebar-label space">QUICK REFERENCE</div>${nav('pediatric','Pediatric calculator','child')}${nav('protocol','Protocol library','book')}<div class="side-footer"><span class="status-dot"></span> 2026 Southwest Ohio<div>Version 2.9.26 · Review prototype</div></div></aside><div class="workspace"><header><div class="crumb">EMS Field Guide <span>/</span> <b>${page==='home'?'Overview':page==='pediatric'?'Pediatrics':page==='protocol'?'Protocol library':modules.find(m=>m.id===page)?.short||'Overview'}</b></div><span class="draft">REVIEW BUILD</span><button class="button small" data-action="new">${icon('plus')} New encounter</button></header><main>${page==='home'?home():page==='pediatric'?pediatric():page==='protocol'?library():detail(modules.find(m=>m.id===page)||modules[0])}</main><footer>WOODLAWN FD <span>Built for a clear next step.</span><span>Prototype · Clinical validation pending</span></footer></div>${modal?dialog():''}`;}
function home(){const matches=modules.filter(m=>(m.title+' '+m.desc).toLowerCase().includes(query.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow">WOODLAWN FIRE DEPARTMENT</div><h1>Ready for the next call.</h1><p>Your checklists, critical reminders, and pediatric references. Together.</p></div><div class="edition">${icon('shield')}<span>Southwest Ohio<b>2026 protocols</b></span></div></div><div class="review-banner"><span class="mini-badge">DRAFT</span>Working prototype for department review. Verify clinical content before field use.<button data-page="protocol">View sources ${icon('arrow')}</button></div><div class="dashboard"><div><div class="section-top"><h2>Clinical checklists <span>06</span></h2><label class="search">${icon('search')}<input id="search" aria-label="Search checklists" placeholder="Find a checklist…" value="${esc(query)}"><kbd>/</kbd></label></div><div class="cards">${matches.map(m=>`<button class="module-card ${m.color}" data-page="${m.id}"><div class="card-top"><div class="module-icon">${icon(m.icon)}</div><span>${m.tag}</span>${icon('arrow')}</div><h3>${m.title}</h3><p>${m.desc}</p><div class="card-bottom"><span>${completed(m)?`${completed(m)} / ${count(m)} complete`:`${count(m)} checklist steps`}</span><span>Open checklist ↗</span></div></button>`).join('')||'<p class="empty">No matching checklist. Try “airway” or “trauma”.</p>'}</div><button class="pediatric-banner" data-page="pediatric"><div class="module-icon">${icon('child')}</div><div><span class="eyebrow">SMALL PATIENTS. CLEAR NUMBERS.</span><h3>Pediatric quick reference</h3><p>Select an age. See estimated weight, medication references, and energy.</p></div><span class="round-arrow">${icon('arrow')}</span></button></div><aside class="right-rail"><section class="panel encounter"><div class="section-top"><h2>Current encounter</h2><span class="tiny-dot"></span></div><p class="muted">Progress stays in this browser tab.</p><div class="encounter-stat"><strong>${String(totalChecks()).padStart(2,'0')}</strong><span>steps checked<br>across your checklists</span></div><div class="thin-progress"><span style="width:${totalChecks()/modules.reduce((n,m)=>n+count(m),0)*100}%"></span></div><div class="encounter-links">${modules.filter(m=>completed(m)).map(m=>`<button data-page="${m.id}">${m.short}<span>${completed(m)}/${count(m)} ${icon('arrow')}</span></button>`).join('')||'<p>Open a checklist to get started.</p>'}</div></section>${timerPanel()}<section class="rail-note">${icon('book')}<h3>A reference you can trace.</h3><p>Each module links to the Southwest Ohio protocol. Your original checklists shape the workflow.</p>${source('Open full protocol')}</section></aside></div>`;}
function timerPanel(){return `<section class="panel timer"><div class="section-top"><h2>${icon('clock')} Event timer</h2><span class="timer-label">ELAPSED</span></div><div class="timer-digits" role="timer">${timerText()}</div><div class="timer-actions"><button class="button primary" data-action="timer">${state.running?'Pause':'Start timer'}</button><button class="button icon-button" data-action="reset-timer" aria-label="Reset timer">${icon('reset')}</button></div><p class="muted">Manual elapsed timer; no clinical alarms.</p></section>`;}
function timerText(){const ms=state.elapsed+(state.running?Date.now()-state.started:0);const s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function detail(m){return `<button class="back" data-page="home">← All checklists</button><div class="page-heading detail-heading"><div><div class="eyebrow ${m.color}">${m.tag}</div><h1>${m.title}</h1><p>${m.desc}</p></div><div class="large-icon ${m.color}">${icon(m.icon)}</div></div><div class="detail-meta">${source(m.source,m.page)}<span>Draft workflow · confirm applicable scope and orders</span></div><div class="detail-layout"><div>${m.id==='cardio'?'<div class="callout amber"><b>Confirm the therapy pathway.</b> SYNC applies to synchronized cardioversion. Pulseless VF/VT uses unsynchronized defibrillation. Reconfirm SYNC markers before every synchronized shock.</div>':''}${m.id==='sedation'?'<div class="callout purple"><b>Sedation is indication-specific.</b> Cardioversion, restraint, and post-intubation care have different requirements. Use the linked pathway and medical-control orders; this checklist does not provide a universal sedation dose.</div>':''}${m.id==='ams'?amsFields():''}<div class="checklist-progress"><b>${completed(m)} of ${count(m)} steps complete</b><span>${Math.round(completed(m)/count(m)*100)}%</span><div class="thin-progress"><span style="width:${completed(m)/count(m)*100}%"></span></div></div>${m.sections.map((section,si)=>`<section class="check-section"><h2><span>${String(si+1).padStart(2,'0')}</span>${section[0]}</h2>${section[1].map((item,ii)=>{const id=`${m.id}-${si}-${ii}`;return `<label class="check-row ${state.checks[id]?'checked':''}"><input type="checkbox" data-check="${id}" ${state.checks[id]?'checked':''}><span class="custom-check">${icon('check')}</span><span>${item}</span></label>`;}).join('')}</section>`).join('')}${m.id==='ams'?amsCauses():''}${m.id==='sick'?`<section class="panel"><h2>Reversible causes review</h2><div class="cause-tags">${['Hypoxia','Hypovolemia','Hydrogen ion / acidosis','Hypo- / hyperkalemia','Hypothermia','Tension pneumothorax','Tamponade','Thrombosis','Toxins','Trauma'].map(c=>`<span>${c}</span>`).join('')}</div></section>`:''}</div><aside class="right-rail">${timerPanel()}<section class="panel"><h2>Related tools</h2>${(m.id==='ams'?['sick','trauma']:m.id==='intubation'?['sedation','sick']:['intubation','ams']).map(id=>{const r=modules.find(x=>x.id===id);return `<button class="tool-link" data-page="${id}">${icon(r.icon)}${r.short}${icon('arrow')}</button>`}).join('')}<button class="tool-link" data-page="pediatric">${icon('child')}Pediatric reference${icon('arrow')}</button></section><section class="rail-note"><h3>One encounter, connected.</h3><p>Switch between modules without losing your checks. Start a new encounter to clear progress, AMS entries, and the timer.</p></section></aside></div>`;}
function field(id,label,type='text',placeholder=''){return `<label class="field">${label}<input type="${type}" data-field="${id}" value="${esc(state.fields[id])}" placeholder="${placeholder}"></label>`;}
function amsFields(){return `<section class="panel ams-history"><div class="section-top"><h2>Establish the timeline</h2><span class="mini-badge">AMS</span></div><div class="fields">${field('lkw','Last known well · local date & time','datetime-local')}${field('onset','Symptom onset · local date & time','datetime-local')}${field('baseline','Baseline mental status','text','Usual orientation / function')}${field('glucose','Blood glucose · mg/dL','number','Value')}</div><label class="inline-check"><input type="checkbox" data-field-check="lkwUnknown" ${state.fields.lkwUnknown?'checked':''}> Last known well is unknown</label><p class="muted">Use this prototype with simulated data. Entries stay in this tab and clear with New encounter.</p></section>`;}
function amsCauses(){return `<section class="panel differential"><h2>Work through possible causes</h2><p class="muted">Statuses record your assessment; they are not an automated diagnosis.</p>${causes.map(([id,title,desc])=>`<div class="cause-row"><div><h3>${title}</h3><p>${desc}</p></div><div class="segments" role="group" aria-label="${title}">${[['unassessed','Unassessed'],['in','Ruled in'],['out','Ruled out']].map(([v,l])=>`<button data-cause="${id}" data-value="${v}" aria-pressed="${(state.causes[id]||'unassessed')===v}" class="${(state.causes[id]||'unassessed')===v?'selected '+v:''}">${l}</button>`).join('')}</div></div>`).join('')}</section>`;}
function pediatric(){const i=state.age,w=i===null?null:weights[i],energy=energies(i,Number(state.adultMax));const filtered=medications.filter(m=>(m.name+' '+m.route+' '+m.concentration).toLowerCase().includes(state.filter.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow teal">PEDIATRIC QUICK REFERENCE</div><h1>Small patients. Clear numbers.</h1><p>Age-based reference cards from the 2026 Southwest Ohio protocol.</p></div><div class="large-icon teal">${icon('child')}</div></div><div class="callout amber"><b>Estimated age is a lookup, not a measured weight.</b> These are the exact age / weight columns from Appendix J. No interpolation between ages. Confirm actual weight or a validated length-based system and the full indication before clinical use. Prototype validation is pending.</div><section class="panel age-panel"><div class="section-top"><h2>01 <span>Select the reference age</span></h2>${source('Appendix J · pp. 237–238',237)}</div><div class="age-grid">${ages.map((a,n)=>`<button data-age="${n}" class="${i===n?'selected':''}" aria-pressed="${i===n}"><b>${a}</b><span>${weights[n]} kg est.</span></button>`).join('')}</div></section>${i===null?'<div class="empty-state">'+icon('child')+'<h2>Choose an age to open its reference card.</h2><p>Medication dose, concentration, route, and volume appear together.</p></div>':`<div class="peds-summary"><section><span>REFERENCE AGE</span><b>${ages[i]}</b></section><section><span>ESTIMATED WEIGHT</span><b>${w} <small>kg</small></b></section><section><span>LOW SYSTOLIC · APP J</span><b>${['60–70','70','70–75','75–80','80','80','85','85','90'][i]} <small>mmHg</small></b></section><section><span>PULSE · APP J</span><b>${['100–180','100–180','90–160','80–140','70–130','70–130','60–120','60–120','60–120'][i]} <small>/min</small></b></section></div><section class="panel energy-panel"><div class="section-top"><h2>${icon('bolt')} Defibrillation · VF / pulseless VT</h2>${source('P601 · p. 152',152)}</div><label class="field cap-field">Adult energy ceiling for your device / protocol<select id="adult-max"><option value="">Select the applicable limit</option><option value="200" ${state.adultMax==='200'?'selected':''}>200 J</option><option value="360" ${state.adultMax==='360'?'selected':''}>360 J</option></select></label><div class="energy-grid"><div><span>INITIAL · 2 J/kg</span><b>${energy?energy[0]+' J':'—'}</b></div><div><span>SECOND · 4 J/kg</span><b>${energy?energy[1]+' J':'—'}</b></div><div><span>SUBSEQUENT · 4–10 J/kg</span><b>${energy?energy[1]+'–'+energy[2]+' J':'—'}</b></div></div><p class="muted">${energy?'Based on '+w+' kg estimated weight. Rounded up and capped at the selected adult dose.':'Select an adult energy ceiling to calculate capped values.'} Newborn resuscitation follows P600.</p><details><summary>Synchronized cardioversion · PSVT</summary><p>P604: medical-control order required. At ${w} kg estimated weight: ${Math.ceil(w*.5)} J → ${w} J → ${w*2} J. Confirm SYNC before each shock.</p>${source('P604 · p. 155',155)}</details></section><section class="panel medication-panel"><div class="section-top"><h2>Medication & fluid reference <span>${medications.length}</span></h2><label class="search">${icon('search')}<input id="med-search" aria-label="Filter medications" placeholder="Find medication or route…" value="${esc(state.filter)}"></label></div><p class="muted">App J reference entries only; not a treatment sequence. Check the full indication, age eligibility, repeat limits, and required orders. “Not available” includes source N/A and cells held for review.</p><div class="table-scroll"><table><thead><tr><th>Medication / indication</th><th>Route · concentration</th><th>Dose</th><th>Volume</th></tr></thead><tbody>${filtered.map(m=>`<tr><td><b>${m.name}</b>${m.note?`<details><summary>Reference note</summary><p>${m.note}</p></details>`:''}<a class="table-source" href="${protocol}#page=${m.page}" target="_blank" rel="noopener">App J · ${m.page} ↗</a></td><td>${m.route}<small>${m.concentration}</small></td><td class="dose">${m.doses[i]===null?'<span class="na">Not available<br>Review source / medical control</span>':`${m.doses[i]} <small>${m.unit}</small>`}</td><td>${m.doses[i]===null?'—':m.volumes?m.volumes[i]+' mL':m.unit==='mL'?'Included in dose':'See source'}</td></tr>`).join('')||'<tr><td colspan="4">No matching medication.</td></tr>'}</tbody></table></div></section>`}`;}
function library(){return `<div class="page-heading"><div><div class="eyebrow">SOURCE OF TRUTH</div><h1>Protocol library</h1><p>Know where each checklist and reference comes from.</p></div></div><section class="protocol-hero"><div>${icon('book')}<h2>Southwest Ohio EMS Protocols</h2><p>Academy of Medicine of Cincinnati · 2026</p><span>Version 2.9.26 · Supplied by you</span></div>${source('Open governing protocol')}</section><section class="panel"><h2>Module references</h2>${modules.map(m=>`<div class="library-row"><div><b>${m.title}</b><p>${m.source}</p></div>${source('Open protocol',m.page)}</div>`).join('')}<div class="library-row"><div><b>Pediatric medication and energy references</b><p>Appendix J · P601 · P604</p></div>${source('Open Appendix J',237)}</div></section><section class="panel"><h2>Review notes</h2><ul class="review-list"><li>Workflow structure is adapted from your sick patient, cardioversion, intubation, trauma, and AMS checklists. These prompts are not a complete protocol.</li><li>The provided pediatric reference includes 2025 tables. This prototype uses the linked 2026 Appendix J columns.</li><li>The 15 kg amiodarone cell, 5 kg D25 cell, and glucagon values are withheld because of source dose / unit inconsistencies.</li><li>Age presets are estimates. Intermediate ages and measured-weight medication calculations are not implemented in this first structure.</li><li>Adult drug and energy tables, department-specific equipment, and clinical release review are the next content pass.</li></ul></section><section class="panel"><h2>About this prototype</h2><p>Checklists, AMS assessment, timer, and pediatric selection share one encounter in this browser tab. No patient account, backend patient record, or offline guarantee is provided. Use simulated data while reviewing. New encounter clears tab-stored entries.</p></section>`;}
function dialog(){return `<div class="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="module-icon red">${icon('reset')}</div><h2 id="dialog-title">Start a new encounter?</h2><p>This clears all checklist progress, AMS entries, pediatric selections, and the timer in this tab.</p><div><button class="button" data-action="cancel">Keep current encounter</button><button class="button primary" data-action="confirm-new">Clear & start new</button></div></section></div>`;}
function render(){document.querySelector('#app').innerHTML=shell();document.title=`${page==='home'?'Overview':page==='pediatric'?'Pediatric reference':page==='protocol'?'Protocol library':modules.find(m=>m.id===page)?.title||'Overview'} · Woodlawn FD`;if(state.fields.lkwUnknown){const lkw=document.querySelector('[data-field="lkw"]');if(lkw)lkw.disabled=true;}if(modal)document.querySelector('[data-action="cancel"]').focus();}
function go(id){page=id;location.hash=id;render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.age!==undefined){state.age=Number(b.dataset.age);save();render();}if(b.dataset.cause){state.causes[b.dataset.cause]=b.dataset.value;save();render();}switch(b.dataset.action){case 'new':modal=true;render();break;case 'cancel':modal=false;render();break;case 'confirm-new':state=blank();save();modal=false;go('home');break;case 'timer':if(state.running){state.elapsed+=Date.now()-state.started;state.running=false;state.started=null;}else{state.started=Date.now();state.running=true;}save();render();break;case 'reset-timer':state.elapsed=0;state.running=false;state.started=null;save();render();break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-check="${el.dataset.check}"]`)?.focus({preventScroll:true});}if(el.dataset.fieldCheck){state.fields[el.dataset.fieldCheck]=el.checked;if(el.dataset.fieldCheck==='lkwUnknown'&&el.checked)state.fields.lkw='';save();render();}if(el.id==='adult-max'){state.adultMax=el.value;save();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){state.fields[el.dataset.field]=el.value;save();}if(el.id==='search'||el.id==='med-search'){const pos=el.selectionStart;if(el.id==='search')query=el.value;else{state.filter=el.value;save();}render();const replacement=document.getElementById(el.id);replacement.focus();replacement.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=false;render();}if(e.key==='Tab'&&modal){const focusable=[...document.querySelectorAll('.dialog button')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const s=document.getElementById('search')||document.getElementById('med-search');if(s){e.preventDefault();s.focus();}}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();});
setInterval(()=>{document.querySelectorAll('.timer-digits').forEach(e=>e.textContent=timerText());},500);
render();
